const http=require('http'),fs=require('fs'),crypto=require('crypto'),{Pool}=require('pg');
const pool=new Pool({connectionString:process.env.DATABASE_URL,ssl:{rejectUnauthorized:false},max:5});
const animals=['lynx','snow-leopard','fox','wolf','raccoon','rabbit','bear','squirrel','panda','deer','eagle-owl','wildcat'];
const schema="ALTER TABLE mountain_rooms ADD COLUMN IF NOT EXISTS ends_at timestamptz;\nALTER TABLE mountain_rooms ADD COLUMN IF NOT EXISTS game_version integer NOT NULL DEFAULT 1;\nCREATE TABLE IF NOT EXISTS mountain_quest_progress (\n room_code text NOT NULL REFERENCES mountain_rooms(code),\n player_id uuid NOT NULL REFERENCES mountain_players(id),\n quest integer NOT NULL CHECK(quest BETWEEN 1 AND 12),\n answered integer NOT NULL DEFAULT 0 CHECK(answered BETWEEN 0 AND 10),\n correct integer NOT NULL DEFAULT 0 CHECK(correct BETWEEN 0 AND answered),\n reward text CHECK(reward = 'gold'),\n completed_at timestamptz,\n PRIMARY KEY(room_code,player_id,quest)\n);\n";
const GAME_SECONDS=3600,QUEST_QUESTIONS=10;
const json=(res,status,obj)=>{res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'});res.end(JSON.stringify(obj))};
async function tx(fn){const c=await pool.connect();try{await c.query('BEGIN');const r=await fn(c);await c.query('COMMIT');return r}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}
async function locked(c,code){const r=await c.query('SELECT * FROM mountain_rooms WHERE code=$1 FOR UPDATE',[code]);if(!r.rowCount)throw Error('Комната не найдена');return r.rows[0]}
function remainingSeconds(room,now=Date.now()){if(!room.started_at)return GAME_SECONDS;if(room.status==='finished')return 0;const end=room.ends_at?new Date(room.ends_at).getTime():new Date(room.started_at).getTime()+GAME_SECONDS*1000;return Math.max(0,Math.ceil((end-(room.status==='paused'?new Date(room.paused_at).getTime():now))/1000))}
function chestKind(correct,total=QUEST_QUESTIONS){return correct*100>=total*70?'gold':null}
function rankPlayers(players){return [...players].sort((a,b)=>b.chests.gold-a.chests.gold||(new Date(a.last_gold_at||8640000000000000)-new Date(b.last_gold_at||8640000000000000))||a.position-b.position)}
function winnerIds(players,finished){if(!finished||!players.length||!players.some(p=>p.chests.gold>0))return [];return [rankPlayers(players)[0].id]}
async function recordAttempt(c,code,questionId,playerId,correct){await c.query('INSERT INTO mountain_attempts(room_code,question_id,player_id,correct) VALUES($1,$2,$3,$4)',[code,questionId,playerId,correct]);await c.query('INSERT INTO mountain_answers(room_code,question_id,player_id,correct) VALUES($1,$2,$3,$4) ON CONFLICT DO NOTHING',[code,questionId,playerId,correct])}
async function finishDeadline(c,room){if(room.status==='playing'&&remainingSeconds(room)===0){await c.query("UPDATE mountain_rooms SET status='finished' WHERE code=$1",[room.code]);await c.query('DELETE FROM mountain_current WHERE room_code=$1',[room.code]);room.status='finished'}return room}
async function progressFor(c,code,player){const quest=Math.floor(Number(player.altitude)/1000)+1;if(quest>12)return null;await c.query('INSERT INTO mountain_quest_progress(room_code,player_id,quest) VALUES($1,$2,$3) ON CONFLICT DO NOTHING',[code,player.id,quest]);return (await c.query('SELECT * FROM mountain_quest_progress WHERE room_code=$1 AND player_id=$2 AND quest=$3',[code,player.id,quest])).rows[0]}
async function advanceTurn(c,code,position){const live=(await c.query('SELECT id,position FROM mountain_players WHERE room_code=$1 AND active AND finished_at IS NULL ORDER BY position',[code])).rows;const next=live.findIndex(x=>x.position>position);await c.query('UPDATE mountain_rooms SET turn_no=$2,status=CASE WHEN $3 THEN $4 ELSE status END WHERE code=$1',[code,next<0?0:next,live.length===0,'finished'])}
async function applyQuestionResult(c,code,player,question,correct){
 const progress=await progressFor(c,code,player);if(!progress||progress.completed_at)throw Error('Квест уже завершён');
 await recordAttempt(c,code,question.id,player.id,correct);
 const answered=progress.answered+1,right=progress.correct+(correct?1:0),completed=answered>=QUEST_QUESTIONS,reward=completed?chestKind(right):null;
 await c.query('UPDATE mountain_quest_progress SET answered=$4,correct=$5,reward=$6,completed_at=CASE WHEN $7 THEN now() ELSE NULL END WHERE room_code=$1 AND player_id=$2 AND quest=$3',[code,player.id,progress.quest,answered,right,reward,completed]);
 const altitude=(progress.quest-1)*1000+answered*100;
 await c.query('UPDATE mountain_players SET altitude=$2,correct=correct+$3,finished_at=CASE WHEN $2>=12000 THEN now() ELSE NULL END WHERE id=$1',[player.id,altitude,correct?1:0]);
 await c.query('DELETE FROM mountain_current WHERE room_code=$1',[code]);await advanceTurn(c,code,player.position);
 return {correct,quest:progress.quest,answered,total:QUEST_QUESTIONS,questCorrect:right,chestAward:reward};
}
async function expireQuestion(c,code,room){if(room.status!=='playing')return;const cur=(await c.query('SELECT * FROM mountain_current WHERE room_code=$1',[code])).rows[0];if(!cur||Date.now()-new Date(cur.created_at).getTime()<30000)return;const p=(await c.query('SELECT * FROM mountain_players WHERE id=$1 AND room_code=$2',[cur.player_id,code])).rows[0];const q=(await c.query('SELECT * FROM mountain_questions WHERE id=$1',[cur.question_id])).rows[0];if(p&&q)await applyQuestionResult(c,code,p,q,false)}
async function assign(c,code,player){const progress=await progressFor(c,code,player);if(!progress)return null;const difficulty=progress.answered<3?'easy':progress.answered<6?'medium':'hard';const q=await c.query(`SELECT q.id FROM mountain_questions q WHERE q.quest=$1 AND NOT EXISTS(SELECT 1 FROM mountain_attempts a WHERE a.room_code=$2 AND a.player_id=$3 AND a.question_id=q.id) ORDER BY CASE WHEN q.difficulty=$4 THEN 0 ELSE 1 END,q.id LIMIT 1`,[progress.quest,code,player.id,difficulty]);if(!q.rowCount)throw Error('Нет вопросов для квеста '+progress.quest);await c.query('INSERT INTO mountain_current(room_code,player_id,question_id) VALUES($1,$2,$3) ON CONFLICT(room_code) DO UPDATE SET player_id=EXCLUDED.player_id,question_id=EXCLUDED.question_id,created_at=now()',[code,player.id,q.rows[0].id]);return q.rows[0].id}
async function attachChests(c,code,players){const rows=(await c.query('SELECT player_id,quest,answered,correct,reward,completed_at FROM mountain_quest_progress WHERE room_code=$1 ORDER BY quest',[code])).rows;for(const p of players){p.questResults=rows.filter(r=>r.player_id===p.id);p.chests={gold:p.questResults.filter(r=>r.reward==='gold').length};p.last_gold_at=p.questResults.filter(r=>r.reward==='gold').map(r=>r.completed_at).sort((a,b)=>new Date(b)-new Date(a))[0]||null}}
async function revisionFor(c,code,id){return (await c.query(`SELECT q.quest,q.topic,count(*)::int mistakes FROM mountain_attempts a JOIN mountain_questions q ON q.id=a.question_id WHERE a.room_code=$1 AND a.player_id=$2 AND NOT a.correct GROUP BY q.quest,q.topic ORDER BY q.quest,mistakes DESC,q.topic`,[code,id])).rows}
async function state(c,code,playerId){let room=await locked(c,code);await finishDeadline(c,room);await expireQuestion(c,code,room);room=await locked(c,code);const players=(await c.query('SELECT id,name,animal,outfit_color,position,altitude,correct,active,finished_at,skipped_quests FROM mountain_players WHERE room_code=$1 ORDER BY position',[code])).rows;await attachChests(c,code,players);const live=players.filter(x=>x.active&&!x.finished_at),turn=['playing','paused'].includes(room.status)&&live.length?live[room.turn_no%live.length]:null;let cur=(await c.query('SELECT q.id,q.quest,q.difficulty,q.topic,q.question_ru,q.options_ru,m.created_at FROM mountain_current m JOIN mountain_questions q ON q.id=m.question_id WHERE m.room_code=$1',[code])).rows[0];if(!cur&&turn&&room.status==='playing'){await assign(c,code,turn);cur=(await c.query('SELECT q.id,q.quest,q.difficulty,q.topic,q.question_ru,q.options_ru,m.created_at FROM mountain_current m JOIN mountain_questions q ON q.id=m.question_id WHERE m.room_code=$1',[code])).rows[0]}const me=players.find(p=>p.id===playerId);return {room:code,sessionNumber:room.session_number,status:room.status,remaining:remainingSeconds(room),players,winnerIds:winnerIds(players,room.status==='finished'),host:players.find(p=>p.active)?.id,turn:turn?.id||null,question:turn?.id===playerId?cur:null,questionRemaining:cur?Math.max(0,Math.ceil((30000-((room.status==='paused'?new Date(room.paused_at).getTime():Date.now())-new Date(cur.created_at).getTime()))/1000)):null,questionPending:!!cur,me:playerId,review:room.status==='finished'||me?.finished_at?await revisionFor(c,code,playerId):[],used:(await c.query('SELECT count(*)::int n FROM mountain_attempts WHERE room_code=$1',[code])).rows[0].n}}
async function action(body){return tx(async c=>{const type=body.action;if(type==='create'){let code;do{code=crypto.randomBytes(3).toString('hex').toUpperCase()}while((await c.query('SELECT 1 FROM mountain_rooms WHERE code=$1',[code])).rowCount);const created=await c.query("INSERT INTO mountain_rooms(code,session_number,game_version) VALUES($1,nextval('mountain_session_seq'),2) RETURNING session_number",[code]);return {code,sessionNumber:created.rows[0].session_number}}const code=String(body.code||'').trim().toUpperCase();if(!/^[A-F0-9]{6}$/.test(code))throw Error('Неверный код комнаты');const room=await locked(c,code);await finishDeadline(c,room);
if(type==='lobby')return {status:room.status,players:(await c.query('SELECT animal,outfit_color FROM mountain_players WHERE room_code=$1',[code])).rows};
if(type==='join'){if(room.status!=='lobby')throw Error('Игра уже началась');const animal=String(body.animal||'');if(!animals.includes(animal))throw Error('Выбери животное');const outfits=['gold','silver','red','yellow','green','sky','black','orange','white','blue','darkgreen','pink'],names=['Рысь','Снежный барс','Лиса','Волк','Енот','Заяц','Белый медведь','Белка','Панда','Олень','Филин','Дикий кот'];const count=(await c.query('SELECT count(*)::int n FROM mountain_players WHERE room_code=$1',[code])).rows[0].n;if(count>=7)throw Error('Комната заполнена');const id=crypto.randomUUID(),i=animals.indexOf(animal);await c.query('INSERT INTO mountain_players(id,room_code,name,animal,position,outfit_color) VALUES($1,$2,$3,$4,$5,$6)',[id,code,names[i],animal,count,outfits[i]]);return {id,code}}
const id=String(body.id||''),p=(await c.query('SELECT * FROM mountain_players WHERE id=$1 AND room_code=$2',[id,code])).rows[0];if(!p)throw Error('Игрок не найден');if(type==='state')return state(c,code,id);
const host=(await c.query('SELECT id FROM mountain_players WHERE room_code=$1 AND active ORDER BY position LIMIT 1',[code])).rows[0]?.id;
if(type==='start'){if(room.status!=='lobby')throw Error('Уже начато');if(host!==id)throw Error('Начать может только первый игрок');await c.query("UPDATE mountain_rooms SET status='playing',started_at=now(),ends_at=now()+interval '60 minutes',turn_no=0 WHERE code=$1",[code]);return state(c,code,id)}
if(type==='pause'){if(host!==id)throw Error('Паузу включает первый игрок');if(room.status!=='playing')throw Error('Игра сейчас не идёт');await c.query("UPDATE mountain_rooms SET status='paused',paused_at=now() WHERE code=$1",[code]);return state(c,code,id)}
if(type==='resume'){if(host!==id)throw Error('Продолжить может первый игрок');if(room.status!=='paused')throw Error('Игра не на паузе');await c.query('UPDATE mountain_current SET created_at=created_at+(now()-(SELECT paused_at FROM mountain_rooms WHERE code=$1)) WHERE room_code=$1',[code]);await c.query("UPDATE mountain_rooms SET status='playing',ends_at=COALESCE(ends_at,started_at+interval '60 minutes')+(now()-paused_at),paused_at=NULL WHERE code=$1",[code]);return state(c,code,id)}
if(!['answer','skipQuest'].includes(type))throw Error('Неизвестная команда');if(room.status!=='playing')return state(c,code,id);await expireQuestion(c,code,room);const fresh=await locked(c,code),live=(await c.query('SELECT * FROM mountain_players WHERE room_code=$1 AND active AND finished_at IS NULL ORDER BY position',[code])).rows;if(live[fresh.turn_no%live.length]?.id!==id)throw Error('Сейчас не твой ход');const player=live.find(x=>x.id===id);if(!player)return state(c,code,id);
if(type==='skipQuest'){const progress=await progressFor(c,code,player);if(Number(body.quest)!==progress.quest)return state(c,code,id);await c.query("UPDATE mountain_quest_progress SET answered=10,reward=NULL,completed_at=now() WHERE room_code=$1 AND player_id=$2 AND quest=$3 AND completed_at IS NULL",[code,id,progress.quest]);const altitude=progress.quest*1000;await c.query('UPDATE mountain_players SET altitude=$2,skipped_quests=array_append(skipped_quests,$3::int),finished_at=CASE WHEN $2>=12000 THEN now() ELSE NULL END WHERE id=$1',[id,altitude,progress.quest]);await c.query('DELETE FROM mountain_current WHERE room_code=$1',[code]);await advanceTurn(c,code,player.position);return {feedback:{skipped:true,quest:progress.quest},...(await state(c,code,id))}}
const cur=(await c.query('SELECT * FROM mountain_current WHERE room_code=$1',[code])).rows[0];if(!cur||body.questionId!==cur.question_id||cur.player_id!==id)return state(c,code,id);const q=(await c.query('SELECT * FROM mountain_questions WHERE id=$1',[cur.question_id])).rows[0];const choice=Number(body.choice);if(!Number.isInteger(choice)||choice<0||choice>=q.options_ru.length)throw Error('Выбери ответ');const feedback=await applyQuestionResult(c,code,player,q,choice===q.correct_index);return {feedback:{...feedback,explanation:q.explanation_ru,correctAnswer:q.options_ru[q.correct_index]},...(await state(c,code,id))}
})}
