const clearQuizAndHikers="<style id=\"serpantin-clear-quiz-and-hikers\">\n#game:not([hidden]) .cloud{background:transparent!important;border:0!important;box-shadow:none!important;backdrop-filter:none!important;border-radius:0!important;top:clamp(72px,13dvh,145px)!important;max-height:48dvh!important;padding:8px 12px!important;color:#102d40!important;text-shadow:0 1px 4px #ffffff,0 0 10px #ffffff!important}\n#game:not([hidden]) .cloud::before,#game:not([hidden]) .cloud::after{display:none!important}\n#game:not([hidden]) .cloud #answers button{background:rgba(235,247,255,.79)!important;border:2px solid rgba(75,133,170,.85)!important;backdrop-filter:blur(4px)!important;box-shadow:0 2px 6px #102f4033!important}\n#game:not([hidden]) .cloud h2,#game:not([hidden]) .cloud h3,#game:not([hidden]) .cloud p{color:#102d40!important;text-shadow:0 1px 6px white,0 0 12px white!important}\n#game:not([hidden]) #climbers{z-index:50!important;overflow:visible!important}\n#game:not([hidden]) #climbers .climber{z-index:51!important;opacity:1!important;visibility:visible!important;display:block!important;filter:drop-shadow(0 2px 3px #0008)!important}\n#game:not([hidden]) #climbers .hiker{opacity:1!important;visibility:visible!important}\n#game:not([hidden]) .frame{background-position:center center!important}\n@media(max-width:700px) and (orientation:portrait){#game:not([hidden]) .cloud{max-height:45dvh!important}#game:not([hidden]) #climbers .climber{min-width:35px!important}}\n</style><script id=\"serpantin-hiker-visibility\">\n(function(){if(typeof render!=='function')return;const previous=render;render=function(){const value=previous.apply(this,arguments);try{\nconst frame=document.querySelector('#game:not([hidden]) .frame');if(!frame||!state||!Array.isArray(state.players))return value;\nconst people=state.players,els=[...frame.querySelectorAll('#climbers .climber')],width=frame.clientWidth,height=frame.clientHeight;if(!width||!height)return value;\nconst vals=people.map(p=>Math.max(0,Number(p.altitude)||0)),low=vals.length?Math.min(...vals):0,high=vals.length?Math.max(...vals):0,range=Math.max(1400,high-low+700),center=(low+high)/2;\nfor(const el of els){const p=people.find(p=>String(p.id)===String(el.dataset.id));if(!p)continue;\nconst i=people.indexOf(p),meters=Math.max(0,Number(p.altitude)||0),u=Math.max(0,Math.min(1,.5+(meters-center)/range));\nconst x=.14+.72*u+((i%3)-1)*.025,y=.78-.28*u;\nel.style.setProperty('left',(x*100).toFixed(2)+'%','important');\nel.style.setProperty('bottom',((1-y)*100).toFixed(2)+'%','important');\nel.style.setProperty('--route-scale',String(Math.max(.65,Math.min(1.05,width/540))));\nel.style.setProperty('visibility','visible','important');el.style.setProperty('opacity','1','important');\nel.style.setProperty('display','block','important');\n}\n}catch(e){console.warn('Serpantin player visibility',e)}return value};})();\n</script>";
