const servedHtml=html.replace('</body>',directionAndRewards+treasureInterface +mobileLayoutFix  +everestCampOverlay+kazakhstanAdventures+kazakhstanBackgrounds+"<style id=\"everest-compact-cloud\">\n#game:not([hidden]) .cloud{position:absolute!important;top:4%!important;left:50%!important;right:auto!important;bottom:auto!important;transform:translateX(-50%)!important;width:min(86vw,430px)!important;max-width:430px!important;max-height:min(34dvh,285px)!important;overflow:auto!important;padding:10px 13px!important;border-radius:48% 48% 34% 34% / 27% 27% 18% 18%!important;background:rgba(249,253,255,.94)!important;color:#18394b!important;box-shadow:0 8px 25px #09253a55!important;z-index:31!important;animation:everestCloudFloat 5s ease-in-out infinite!important}\n#game:not([hidden]) .cloud button{padding:5px 9px!important;font-size:clamp(11px,1.6vw,13px)!important;line-height:1.25!important}\n#game:not([hidden]) .cloud #answers{gap:5px!important}\n#game:not([hidden]) .cloud h2,#game:not([hidden]) .cloud h3{font-size:clamp(13px,2.1vw,17px)!important;margin:3px 0!important}\n#game:not([hidden]) .cloud p{font-size:clamp(11px,1.7vw,14px)!important;margin:4px 0!important}\n#game:not([hidden]) .climber{scale:calc(1.38 * var(--perspective-scale,1))!important;transform-origin:center bottom!important}\n@keyframes everestCloudFloat{0%,100%{translate:0 0}50%{translate:0 -9px}}\n@media(max-width:600px){#game:not([hidden]) .cloud{width:84vw!important;max-height:30dvh!important;padding:9px 12px!important;border-radius:28px!important}#game:not([hidden]) .climber{scale:calc(1.28 * var(--perspective-scale,1))!important}}\n@media(prefers-reduced-motion:reduce){#game:not([hidden]) .cloud{animation:none!important}}\n</style>"+"<style id=\"everest-film-camera\">\n#game:not([hidden]) .frame{position:relative!important;overflow:hidden!important;background:#18323c!important}\n#game:not([hidden]) .frame .quest-scenery{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;background-size:cover!important;background-position:var(--film-pan,0%) center!important;background-repeat:no-repeat!important;transition:background-position .65s ease!important}\n#game:not([hidden]) .climber{transition:left .65s ease,bottom .65s ease!important}\n#game:not([hidden]) .cloud{position:absolute!important;top:48px!important;left:50%!important;right:auto!important;bottom:auto!important;transform:translateX(-50%)!important;translate:none!important;animation:none!important;border-radius:18px!important;width:min(86vw,460px)!important;max-width:460px!important;max-height:34dvh!important;overflow:auto!important;z-index:90!important;padding:10px 12px!important}\n#game:not([hidden]) .cloud #answers{display:grid!important;grid-template-columns:1fr!important;gap:4px!important}\n#game:not([hidden]) .cloud button{min-height:36px!important}\n@media(orientation:landscape) and (max-height:650px){#game:not([hidden]) .cloud{top:5px!important;left:auto!important;right:8px!important;transform:none!important;width:43vw!important;max-width:43vw!important;max-height:calc(100dvh - 10px)!important;overflow-y:auto!important}#game:not([hidden]) .cloud p{font-size:13px!important}#game:not([hidden]) .cloud button{font-size:12px!important;min-height:29px!important;padding:4px!important}}\n</style><script id=\"everest-film-camera-js\">\n(function(){\nif(typeof render!=='function')return;\nconst previousRender=render;\nrender=function(){\nconst result=previousRender.apply(this,arguments);\ntry{\nif(!state||!Array.isArray(state.players))return result;\nconst frame=document.querySelector('#game:not([hidden]) .frame'),scene=frame?.querySelector('.quest-scenery');\nif(!frame||!scene)return result;\nconst fw=frame.clientWidth,fh=frame.clientHeight;\nif(!fw||!fh)return result;\nconst imgRatio=16/9,viewRatio=fw/fh;\nconst imgW=Math.max(fw,fh*imgRatio),imgH=Math.max(fh,fw/imgRatio);\nconst cropX=(imgW-fw)/2,cropY=(imgH-fh)/2;\nconst players=state.players,quest=locationQuest,points=questTrails[quest-1];\nif(!points)return result;\nconst progress=p=>{const q=questOf(p);return q<quest?0:q>quest?1:Math.max(0,Math.min(1,(Number(p.altitude)%1000)/900))};\nconst lead=players.reduce((m,p)=>Math.max(m,progress(p)),0);\nconst portrait=window.matchMedia('(orientation:portrait) and (max-width:700px)').matches;\nconst pan=portrait?lead:0.5;\nscene.style.setProperty('--film-pan',Math.round(pan*100)+'%');\nconst shiftX=portrait?(imgW-fw)*pan:cropX;\nconst shiftY=cropY;\nfor(const el of frame.querySelectorAll('#climbers .climber')){\nconst p=players.find(p=>String(p.id)===String(el.dataset.id));if(!p)continue;\nconst t=progress(p),xy=trailPoint(points,t);\nconst screenX=imgW*xy[0]/100-shiftX,screenY=imgH*xy[1]/100-shiftY;\nel.style.setProperty('left',Math.max(3,Math.min(fw-3,screenX))/fw*100+'%','important');\nel.style.setProperty('bottom',Math.max(9,Math.min(fh-9,fh-screenY))/fh*100+'%','important');\n}\nconst marks=frame.querySelectorAll('.distance-marks .distance-mark');\nmarks.forEach((el,i)=>{const xy=trailPoint(points,i/3);el.style.left=(imgW*xy[0]/100-shiftX)/fw*100+'%';el.style.top=(imgH*xy[1]/100-shiftY)/fh*100+'%'});\n}catch(err){console.warn('Film camera:',err)}\nreturn result;\n};\n})();\n</script>"+finalScreenFix+autumnTheme+bayanaulSerpentine+serpantinBranding+serpantinQuizFix+approvedArtwork+clearQuizAndHikers+fullBackgroundVisible+'</body>');
const server=http.createServer(async(req,res)=>{try{const pathname=new URL(req.url,'http://localhost').pathname;if(req.method==='GET'&&pathname==='/locations/serpantin-go-approved.png'){try{const data=await fs.promises.readFile(__dirname+'/locations/serpantin-go-approved.png');res.writeHead(200,{'Content-Type':'image/png','Cache-Control':'public,max-age=3600'});return res.end(data)}catch(e){res.writeHead(404);return res.end('Approved artwork not uploaded')}}if(req.method==='GET'&&pathname.startsWith('/locations/')&&pathname.endsWith('.jpg')&&/^\/locations\/[0-9]{2}-[a-z-]+\.jpg$/.test(pathname)){const file=__dirname+pathname;try{const data=await fs.promises.readFile(file);res.writeHead(200,{'Content-Type':'image/jpeg','Cache-Control':'public,max-age=3600','X-Content-Type-Options':'nosniff'});return res.end(data)}catch(e){if(e.code!=='ENOENT')throw e;res.writeHead(404);return res.end('Location missing')}}if(pathname==='/health'){await pool.query('SELECT 1');return json(res,200,{ok:true,database:'connected'});}if(req.method==='GET'&&pathname==='/characters/rear-atlas.png'){const data=await fs.promises.readFile(__dirname+'/characters/rear-atlas.png');res.writeHead(200,{'Content-Type':'image/png','Cache-Control':'public,max-age=3600'});return res.end(data)}if(req.method==='GET'&&/^\/characters\/(lynx|snow-leopard|fox|wolf|raccoon|rabbit|bear|squirrel|panda|deer|eagle-owl|wildcat)\.png$/.test(pathname)){const file=__dirname+pathname;try{const data=await fs.promises.readFile(file);res.writeHead(200,{'Content-Type':'image/png','Cache-Control':'public,max-age=3600','X-Content-Type-Options':'nosniff'});return res.end(data)}catch(e){if(e.code!=='ENOENT')throw e;res.writeHead(404);return res.end('Character asset missing')}}if(pathname==='/api'&&req.method==='POST'){let raw='';for await(const part of req){raw+=part;if(raw.length>16000)throw Error('Слишком большой запрос')}const out=await action(JSON.parse(raw));return json(res,200,out)}if(pathname==='/'||pathname==='/index.html'||pathname==='/'+String.fromCharCode(42,42)){res.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});return res.end(servedHtml)}res.writeHead(404);res.end()}catch(e){json(res,400,{error:e.message})}});
if(require.main===module)(async()=>{await pool.query(schema);server.listen(process.env.PORT||10000,'0.0.0.0',()=>console.log('Everest treasure server ready'))})().catch(e=>{console.error(e);process.exit(1)});
